Add-Type -AssemblyName System.IO.Compression

function Convert-DbNumber($Value){
    if($null-eq$Value-or[string]::IsNullOrWhiteSpace([string]$Value)){return $null}
    $n=0.0;if([double]::TryParse(([string]$Value).Replace(',','.'),[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$n)-and-not[double]::IsNaN($n)-and-not[double]::IsInfinity($n)){return $n};return $null
}

function Test-GlassReferenceDatabase {
    param([string]$CatalogPath,[string]$TypeBasePath)
    $issues=New-Object Collections.ArrayList
    function Add-Issue($Level,$Source,$Row,$Field,$Value,$Message){[void]$issues.Add([pscustomobject]@{Уровень=$Level;Источник=$Source;Строка=[int]$Row;Поле=[string]$Field;Значение=[string]$Value;Описание=$Message})}
    $type=@();$catalog=@();$typeHeaders=@('Тип_детали','Подтип','DN','Материал','Труба_исходная','Диаметр_мм','Стенка_мм','Длина_номинал_мм','Длина_с_допуском','Источник','Статус','Варианты_длины_мм')
    if(-not(Test-Path -LiteralPath $TypeBasePath)){Add-Issue 'Ошибка' 'База типоразмеров' 0 '' '' 'Файл отсутствует.'}else{try{$type=@(Import-Csv -LiteralPath $TypeBasePath -Delimiter ';');$h=@((Get-Content -LiteralPath $TypeBasePath -TotalCount 1).Split(';')|ForEach-Object{$_.Trim([char]0xFEFF,'"')});foreach($x in $typeHeaders){if($x-notin$h){Add-Issue 'Ошибка' 'База типоразмеров' 1 $x '' 'Нет обязательного столбца.'}}}catch{Add-Issue 'Ошибка' 'База типоразмеров' 0 '' '' ('Файл не читается: '+$_.Exception.Message)}}
    $seen=@{}
    for($i=0;$i-lt$type.Count;$i++){$r=$type[$i];$line=$i+2
        if([string]::IsNullOrWhiteSpace($r.Тип_детали)){Add-Issue 'Ошибка' 'База типоразмеров' $line 'Тип_детали' '' 'Не указан тип детали.'}
        foreach($f in @('Диаметр_мм','Стенка_мм','Длина_номинал_мм')){$raw=[string]$r.$f;$n=Convert-DbNumber $raw;if($null-eq$n-or$n-le0){Add-Issue 'Ошибка' 'База типоразмеров' $line $f $raw 'Нужно положительное число; даты и текст недопустимы.'};if($raw-match'^\d{1,2}[./-]\d{1,2}([./-]\d{2,4})?$'){Add-Issue 'Ошибка' 'База типоразмеров' $line $f $raw 'Значение похоже на дату.'}}
        if([string]::IsNullOrWhiteSpace($r.DN)){Add-Issue 'Предупреждение' 'База типоразмеров' $line 'DN' '' 'DN не указан.'}
        if($r.Статус-and$r.Статус-ne'однозначно'){Add-Issue 'Предупреждение' 'База типоразмеров' $line 'Статус' $r.Статус 'Строка требует подтверждения.'}
        if($r.Тип_детали-eq'Корпус'-and$r.Труба_исходная-match'(?i)круг.*40|40.*круг'){Add-Issue 'Ошибка' 'База типоразмеров' $line 'Труба_исходная' $r.Труба_исходная 'Корпус из круга 40 запрещён.'}
        $key=(@($r.Тип_детали,$r.Подтип,$r.DN,$r.Материал,$r.Труба_исходная,$r.Длина_номинал_мм)-join'|').ToLowerInvariant();if($seen.ContainsKey($key)){Add-Issue 'Предупреждение' 'База типоразмеров' $line '' $key ("Полный дубль строки $($seen[$key]).")}else{$seen[$key]=$line}
    }
    if(-not(Test-Path -LiteralPath $CatalogPath)){Add-Issue 'Предупреждение' 'Справочник номенклатуры' 0 '' '' 'Ручной справочник отсутствует.'}else{try{$catalog=@(Import-Csv -LiteralPath $CatalogPath -Delimiter ';');$h=@((Get-Content -LiteralPath $CatalogPath -TotalCount 1).Split(';')|ForEach-Object{$_.Trim([char]0xFEFF,'"')});foreach($x in @('Номенклатура','Длина_детали_мм','Примечание')){if($x-notin$h){Add-Issue 'Ошибка' 'Справочник номенклатуры' 1 $x '' 'Нет обязательного столбца.'}}}catch{Add-Issue 'Ошибка' 'Справочник номенклатуры' 0 '' '' ('Файл не читается: '+$_.Exception.Message)}}
    $names=@{};for($i=0;$i-lt$catalog.Count;$i++){$r=$catalog[$i];$line=$i+2;$name=[string]$r.Номенклатура;$n=Convert-DbNumber $r.Длина_детали_мм
        if([string]::IsNullOrWhiteSpace($name)){Add-Issue 'Ошибка' 'Справочник номенклатуры' $line 'Номенклатура' '' 'Пустая номенклатура.'}elseif($names.ContainsKey($name.ToLowerInvariant())){Add-Issue 'Ошибка' 'Справочник номенклатуры' $line 'Номенклатура' $name ("Дубль; первая строка $($names[$name.ToLowerInvariant()]).")}else{$names[$name.ToLowerInvariant()]=$line};if($null-eq$n-or$n-le0){Add-Issue 'Ошибка' 'Справочник номенклатуры' $line 'Длина_детали_мм' $r.Длина_детали_мм 'Нужна конечная положительная длина.'}
    }
    $errors=@($issues|Where-Object Уровень -eq 'Ошибка').Count;$warnings=@($issues|Where-Object Уровень -eq 'Предупреждение').Count;$typeErrors=@($issues|Where-Object{$_.Уровень-eq'Ошибка'-and$_.Источник-eq'База типоразмеров'}).Count
    [pscustomobject]@{Status=$(if($errors){'ОШИБКА'}elseif($warnings){'ЕСТЬ ПРЕДУПРЕЖДЕНИЯ'}else{'ИСПРАВНА'});Errors=$errors;Warnings=$warnings;TypeBaseValid=($typeErrors-eq0);Issues=@($issues)}
}

function Convert-Duration([double]$Seconds){if($Seconds-lt0){$Seconds=0};$ms=[long][math]::Round($Seconds*1000);$h=[math]::Floor($ms/3600000);$ms-=$h*3600000;$m=[math]::Floor($ms/60000);$ms-=$m*60000;$s=[math]::Floor($ms/1000);$z=$ms%1000;'{0:00}:{1:00}:{2:00}.{3:000}'-f$h,$m,$s,$z}
function Xml-Escape($Value){if($null-eq$Value){return''};$s=[regex]::Replace([string]$Value,'[\x00-\x08\x0B\x0C\x0E-\x1F]','');[Security.SecurityElement]::Escape($s)}
function Col-Name([int]$n){$s='';while($n-gt0){$n--;$s=[char](65+$n%26)+$s;$n=[math]::Floor($n/26)};$s}

function New-SheetXml([string[]]$Headers,[object[]]$Rows){
    $all=@(,$Headers)+@($Rows);$width=New-Object int[] $Headers.Count
    for($c=0;$c-lt$Headers.Count;$c++){$width[$c]=[math]::Min(45,[math]::Max(10,$Headers[$c].Length+2))}
    foreach($row in $Rows){for($c=0;$c-lt$Headers.Count;$c++){$v=if($c-lt$row.Count){[string]$row[$c]}else{''};$width[$c]=[math]::Min(45,[math]::Max($width[$c],[math]::Min(45,$v.Length+2)))}}
    $b=New-Object Text.StringBuilder;[void]$b.Append('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>')
    for($c=0;$c-lt$Headers.Count;$c++){[void]$b.Append(('<col min="{0}" max="{0}" width="{1}" customWidth="1"/>'-f($c+1),$width[$c]))};[void]$b.Append('</cols><sheetData>')
    for($r=0;$r-lt$all.Count;$r++){[void]$b.Append(('<row r="{0}">'-f($r+1)));$row=@($all[$r]);for($c=0;$c-lt$Headers.Count;$c++){$ref=(Col-Name ($c+1))+($r+1);$v=if($c-lt$row.Count){$row[$c]}else{$null};$style=if($r-eq0){' s="1"'}else{''};if($null-eq$v-or($v-is[string]-and$v.Length-eq0)){[void]$b.Append("<c r=`"$ref`"$style/>")}elseif($v-is[int]-or$v-is[long]-or$v-is[double]-or$v-is[decimal]){if(($v-is[double])-and([double]::IsNaN([double]$v)-or[double]::IsInfinity([double]$v))){throw "Неконечное число в ячейке $ref"};$n=[string]::Format([Globalization.CultureInfo]::InvariantCulture,'{0}',$v);[void]$b.Append("<c r=`"$ref`"$style><v>$n</v></c>")}else{[void]$b.Append("<c r=`"$ref`"$style t=`"inlineStr`"><is><t xml:space=`"preserve`">$(Xml-Escape $v)</t></is></c>")}};[void]$b.Append('</row>')}
    $last=(Col-Name $Headers.Count)+[math]::Max(1,$all.Count);[void]$b.Append("</sheetData><autoFilter ref=`"A1:$last`"/><pageMargins left=`"0.3`" right=`"0.3`" top=`"0.5`" bottom=`"0.5`" header=`"0.2`" footer=`"0.2`"/></worksheet>");$b.ToString()
}

function Add-ZipText($Zip,$Path,$Text){$e=$Zip.CreateEntry($Path,[IO.Compression.CompressionLevel]::Optimal);$s=$e.Open();try{$w=New-Object IO.StreamWriter($s,(New-Object Text.UTF8Encoding($false)));try{$w.Write($Text)}finally{$w.Dispose()}}finally{$s.Dispose()}}

function New-OpenXmlWorkbook($Sheets,[string]$OutputPath){
    $folder=Split-Path -Parent $OutputPath;if($folder-and-not(Test-Path -LiteralPath $folder)){[void][IO.Directory]::CreateDirectory($folder)};$temp=$OutputPath+'.tmp-'+[guid]::NewGuid().ToString('N');$file=[IO.File]::Open($temp,[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
    try{$zip=New-Object IO.Compression.ZipArchive($file,[IO.Compression.ZipArchiveMode]::Create,$true);try{
        $parts=for($i=1;$i-le$Sheets.Count;$i++){"<Override PartName=`"/xl/worksheets/sheet$i.xml`" ContentType=`"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml`"/>"};Add-ZipText $zip '[Content_Types].xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+($parts-join'')+'</Types>')
        Add-ZipText $zip '_rels/.rels' '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'
        $nodes=for($i=0;$i-lt$Sheets.Count;$i++){"<sheet name=`"$(Xml-Escape $Sheets[$i].Name)`" sheetId=`"$($i+1)`" r:id=`"rId$($i+1)`"/>"};Add-ZipText $zip 'xl/workbook.xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets>'+($nodes-join'')+'</sheets><calcPr calcId="0"/></workbook>')
        $rels=for($i=1;$i-le$Sheets.Count;$i++){"<Relationship Id=`"rId$i`" Type=`"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet`" Target=`"worksheets/sheet$i.xml`"/>"};$rels+="<Relationship Id=`"rId$($Sheets.Count+1)`" Type=`"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles`" Target=`"styles.xml`"/>";Add-ZipText $zip 'xl/_rels/workbook.xml.rels' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+($rels-join'')+'</Relationships>')
        Add-ZipText $zip 'xl/styles.xml' '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="10"/><name val="Arial"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="10"/><name val="Arial"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF1F4E78"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf/><xf fontId="1" fillId="2" applyFont="1" applyFill="1" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'
        for($i=0;$i-lt$Sheets.Count;$i++){Add-ZipText $zip "xl/worksheets/sheet$($i+1).xml" (New-SheetXml $Sheets[$i].Headers $Sheets[$i].Rows)}
    }finally{$zip.Dispose()}}finally{$file.Dispose()};if(Test-Path -LiteralPath $OutputPath){[IO.File]::Delete($OutputPath)};[IO.File]::Move($temp,$OutputPath)
}

function Rows-From($Source,[string[]]$Properties){$out=@();foreach($r in $Source){$row=@();foreach($p in $Properties){$row+=,$r.$p};$out+=,@($row)};,$out}

function Resolve-ReportJobLength([string]$Job,$Catalog,$Types){
    foreach($row in @($Catalog)){if($row.Номенклатура-eq$Job-and-not[string]::IsNullOrWhiteSpace($row.Длина_детали_мм)){$n=Convert-DbNumber $row.Длина_детали_мм;if($null-ne$n-and$n-gt0){return [pscustomobject]@{Length=[double]$n;Status='задана вручную';Reason='Справочник номенклатуры'}}}}
    $name=[IO.Path]::GetFileNameWithoutExtension($Job).ToLowerInvariant();$type='';$subtype='';$special='(?:^|[_\s.\-])(рп|сдз)(?:[_\s.\-]|$)'
    if($name-match'корпус'){$type=if($name-match'муфтов'){'Корпус муфтовый'}elseif($name-match'под\s*врез'){'Корпус под врезку'}elseif($name-match$special){'Корпус РП/СДЗ'}else{'Корпус'}}
    elseif($name-match'патруб'){if($name-match'regula'){$type='Патрубок фланцевый REGULA'}elseif($name-match'energy'){$type='Патрубок фланцевый Energy Gas'}elseif($name-match$special){$type='Патрубок фланцевый РП/СДЗ'}elseif($name-match'привар'){$type='Патрубок приварной';if($name-match'нсд'){$subtype='НСД'}elseif($name-match'ссд'){$subtype='ССД'}}elseif($name-match'фланц'){$type='Патрубок фланцевый ГАЗ/ВОДА'}}
    $dnMatch=[regex]::Match($name,'ду\s*(\d+)\s*[_/]\s*(\d+)','IgnoreCase');if(-not$type-or-not$dnMatch.Success){return [pscustomobject]@{Length=$null;Status='НЕТ ДЛИНЫ';Reason='Из имени не удалось однозначно определить тип детали и DN'}}
    $dn=$dnMatch.Groups[1].Value+'/'+$dnMatch.Groups[2].Value;$matches=@($Types|Where-Object{$baseDn=(([string]$_.DN)-replace'(?i)^ду\s*','')-replace'_','/';$_.Тип_детали-eq$type-and$baseDn-eq$dn-and$_.Статус-eq'однозначно'-and([string]::IsNullOrWhiteSpace($subtype)-or$_.Подтип-eq$subtype)})
    $lengths=@($matches|ForEach-Object Длина_номинал_мм|Where-Object{$_}|ForEach-Object{Convert-DbNumber $_}|Where-Object{$null-ne$_}|Sort-Object -Unique)
    if($lengths.Count-eq1){return [pscustomobject]@{Length=[double]$lengths[0];Status='найдена в базе';Reason='База типоразмеров'}}
    $reason=if($matches.Count-eq0){'В базе нет однозначной строки для распознанных типа и DN'}else{'В базе найдено несколько различных вариантов длины'}
    [pscustomobject]@{Length=$null;Status='НЕТ ДЛИНЫ';Reason=$reason}
}

function Convert-ReportDate($Value,[string]$Context,[switch]$AllowEmpty){if($Value-is[datetime]){return [datetime]$Value};$date=[datetime]::MinValue;if([string]::IsNullOrWhiteSpace([string]$Value)){if($AllowEmpty){return $null};throw "Не указана дата: $Context"};foreach($format in @('o','yyyy-MM-dd HH:mm:ss.fff','yyyy-MM-dd HH:mm:ss')){if([datetime]::TryParseExact([string]$Value,$format,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::AllowWhiteSpaces,[ref]$date)){return $date}};throw "Некорректная дата '$Value': $Context"}

function New-GlassExcelReport {
    param([string]$EventsPath,[string]$GlassesPath,[string]$CatalogPath,[string]$TypeBasePath,[string]$CounterPath,[string]$CounterAuditPath,[string]$CyclesPath,[string]$Station,[string]$OutputPath,[string]$AppVersion='',[string]$DatabaseVersion='')
    $events=if(Test-Path -LiteralPath $EventsPath){@(Import-Csv -LiteralPath $EventsPath -Delimiter ';'|Where-Object Станок -eq $Station)}else{@()};$glasses=if(Test-Path -LiteralPath $GlassesPath){@(Import-Csv -LiteralPath $GlassesPath -Delimiter ';'|Where-Object Станок -eq $Station)}else{@()};$catalog=if(Test-Path -LiteralPath $CatalogPath){@(Import-Csv -LiteralPath $CatalogPath -Delimiter ';')}else{@()};$types=if(Test-Path -LiteralPath $TypeBasePath){@(Import-Csv -LiteralPath $TypeBasePath -Delimiter ';')}else{@()};$counter=if(Test-Path -LiteralPath $CounterPath){@(Import-Csv -LiteralPath $CounterPath -Delimiter ';'|Where-Object Станок -eq $Station)}else{@()};$audit=if($CounterAuditPath-and(Test-Path -LiteralPath $CounterAuditPath)){@(Import-Csv -LiteralPath $CounterAuditPath -Delimiter ';'|Where-Object Станок -eq $Station)}else{@()};$cycles=if(Test-Path -LiteralPath $CyclesPath){@(Import-Csv -LiteralPath $CyclesPath -Delimiter ';'|Where-Object Станок -eq $Station)}else{@()}
    $eventRows=@();foreach($e in $events){$eventRows+=,@($e.Дата_время,$e.UTC,$e.Станок,$e.Оператор,$e.ID_стекла,$e.Номенклатура,$e.Событие,(Convert-DbNumber $e.Длительность_с),$e.Класс,$e.Подробности)}
    $glassRows=@();$ids=@($glasses|ForEach-Object ID_стекла)+@($events|Where-Object Событие -eq 'стекло установлено'|ForEach-Object ID_стекла)|Sort-Object -Unique
    foreach($id in $ids){
        if(-not$id){continue};$g=$glasses|Where-Object ID_стекла -eq $id|Select-Object -First 1;$startEvent=$events|Where-Object{$_.'ID_стекла'-eq$id-and$_.Событие-eq'стекло установлено'}|Select-Object -First 1;$ge=@($events|Where-Object ID_стекла -eq $id)
        $sec=($ge|ForEach-Object{Convert-DbNumber $_.Длительность_с}|Measure-Object -Sum).Sum;if($null-eq$sec){$sec=0};$installed=if($g){$g.Установлено}else{$startEvent.Дата_время};$removed=if($g){$g.Снято}else{''}
        $a=Convert-ReportDate ([string]$installed) "стекло $id установлено";$z=Convert-ReportDate ([string]$removed) "стекло $id снято" -AllowEmpty;$end=if($null-ne$z){$z}else{Get-Date}
        $glassRows+=,@($id,$Station,$(if($g){$g.Оператор_установки}else{$startEvent.Оператор}),$installed,$removed,$(if($g){$g.Оператор_снятия}else{''}),$(if($g){$g.Причина}else{''}),$(if($g){''}else{'Активное стекло'}),[math]::Round($sec,3),(Convert-Duration $sec),@($ge|Where-Object Класс -eq 'короткий импульс').Count,@($ge|Where-Object Класс -eq 'пробивка/настройка').Count,@($ge|Where-Object Класс -eq 'рабочая резка').Count,(Convert-Duration ([math]::Max(0,($end-$a).TotalSeconds))))
    }
    $jobRows=@();foreach($g in ($events|Where-Object{$_.'ID_стекла'-and$_.Номенклатура}|Group-Object ID_стекла,Номенклатура)){$x=$g.Group[0];$sec=($g.Group|ForEach-Object{Convert-DbNumber $_.Длительность_с}|Measure-Object -Sum).Sum;if($null-eq$sec){$sec=0};$resolved=Resolve-ReportJobLength $x.Номенклатура $catalog $types;$jobRows+=,@($Station,$x.ID_стекла,$x.Номенклатура,$resolved.Length,$resolved.Status,[math]::Round($sec,3),(Convert-Duration $sec),@($g.Group|Where-Object Событие -eq 'лазер включён').Count,$g.Count)}
    $allJobs=@(@($events|ForEach-Object Номенклатура)+@($counter|ForEach-Object Номенклатура)+@($cycles|ForEach-Object Номенклатура)|Where-Object{$_}|Sort-Object -Unique);$missingRows=@();foreach($job in $allJobs){$resolved=Resolve-ReportJobLength $job $catalog $types;if($null-eq$resolved.Length){$seen=@(@($events|Where-Object Номенклатура -eq $job|ForEach-Object Дата_время)+@($counter|Where-Object Номенклатура -eq $job|ForEach-Object Дата_время)+@($cycles|Where-Object Номенклатура -eq $job|ForEach-Object Начало)|Where-Object{$_}|Sort-Object);$missingRows+=,@($Station,$job,$(if($seen.Count){$seen[0]}else{''}),$(if($seen.Count){$seen[-1]}else{''}),@($events|Where-Object Номенклатура -eq $job).Count,$resolved.Reason,'','Добавить строку в Справочник_номенклатуры.csv')}}
    $sec=($events|ForEach-Object{Convert-DbNumber $_.Длительность_с}|Measure-Object -Sum).Sum;if($null-eq$sec){$sec=0};$check=Test-GlassReferenceDatabase $CatalogPath $TypeBasePath
    $summary=@(@('Станок',$Station),@('Версия программы',$AppVersion),@('Версия базы',$DatabaseVersion),@('Выгружено',(Get-Date).ToString('yyyy-MM-dd HH:mm:ss')),@('Стёкол всего',$glassRows.Count),@('Время лазера, с',[math]::Round($sec,3)),@('Время лазера',(Convert-Duration $sec)),@('Коротких импульсов',@($events|Where-Object Класс -eq 'короткий импульс').Count),@('Пробивка/настройка',@($events|Where-Object Класс -eq 'пробивка/настройка').Count),@('Рабочих участков',@($events|Where-Object Класс -eq 'рабочая резка').Count),@('Номенклатур',$jobRows.Count),@('Позиций без длины',$missingRows.Count),@('OCR принято',@($audit|Where-Object Решение -eq 'принято').Count),@('OCR отклонено',@($audit|Where-Object Решение -eq 'отклонено').Count),@('Состояние базы',$check.Status),@('Ошибок базы',$check.Errors),@('Предупреждений базы',$check.Warnings))
    $issueRows=Rows-From $check.Issues @('Уровень','Источник','Строка','Поле','Значение','Описание');if(-not$issueRows.Count){$issueRows=@(,@('Готово','Все справочники',0,'','','Ошибок и предупреждений не найдено.'))}
    $s=@([pscustomobject]@{Name='Сводка';Headers=@('Показатель','Значение');Rows=$summary},[pscustomobject]@{Name='Стекла';Headers=@('Стекло','Станок','Оператор установки','Установлено','Снято','Оператор снятия','Причина','Примечание','Время лазера, с','Время лазера','<1 с','1–3 с','>3 с','Срок службы');Rows=$glassRows},[pscustomobject]@{Name='Номенклатура';Headers=@('Станок','Стекло','Номенклатура','Длина, мм','Статус длины','Время лазера, с','Время лазера','Включений','Событий');Rows=$jobRows},[pscustomobject]@{Name='Нет длины';Headers=@('Станок','Номенклатура','Первое появление','Последнее появление','Событий','Почему не определена','Длина для добавления, мм','Действие');Rows=$missingRows},[pscustomobject]@{Name='События';Headers=@('Дата и время','UTC','Станок','Оператор','Стекло','Номенклатура','Событие','Длительность, с','Класс','Подробности');Rows=$eventRows},[pscustomobject]@{Name='Циклы метража';Headers=@('Начало','Окончание','Станок','Оператор','Стекло','Номенклатура','ID цикла','Начальный счётчик','Конечный счётчик','Количество','Длина, мм','Метраж, м','Статус','Причина закрытия');Rows=(Rows-From $cycles @('Начало','Окончание','Станок','Оператор','ID_стекла','Номенклатура','ID_цикла','Начальный_счетчик','Конечный_счетчик','Количество','Длина_детали_мм','Метраж','Статус','Причина_закрытия'))},[pscustomobject]@{Name='Счётчик';Headers=@('Дата и время','Станок','Оператор','Стекло','Номенклатура','ID цикла','Счётчик','Прирост','Количество цикла','Длина, мм','Метраж, м','Режим','Примечание');Rows=(Rows-From $counter @('Дата_время','Станок','Оператор','ID_стекла','Номенклатура','ID_цикла','Счетчик','Прирост','Количество_цикла','Длина_детали_мм','Метраж','Режим','Примечание'))},[pscustomobject]@{Name='Качество OCR';Headers=@('Дата и время','UTC','Станок','Оператор','Стекло','Номенклатура','Текст OCR','Число','Кандидат','Повторов','Решение','Причина','Снимок');Rows=(Rows-From $audit @('Дата_время','UTC','Станок','Оператор','ID_стекла','Номенклатура','Текст_OCR','Распознанное_число','Кандидат','Повторов','Решение','Причина','Снимок'))},[pscustomobject]@{Name='Справочник';Headers=@('Номенклатура','Длина детали, мм','Примечание');Rows=(Rows-From $catalog @('Номенклатура','Длина_детали_мм','Примечание'))},[pscustomobject]@{Name='База типоразмеров';Headers=@('Тип детали','Подтип','DN','Материал','Труба исходная','Диаметр, мм','Стенка, мм','Длина, мм','Длина с допуском','Источник','Статус','Варианты длины, мм');Rows=(Rows-From $types @('Тип_детали','Подтип','DN','Материал','Труба_исходная','Диаметр_мм','Стенка_мм','Длина_номинал_мм','Длина_с_допуском','Источник','Статус','Варианты_длины_мм'))},[pscustomobject]@{Name='Проверка базы';Headers=@('Уровень','Источник','Строка','Поле','Значение','Описание');Rows=$issueRows})
    New-OpenXmlWorkbook $s $OutputPath;return $check
}
